"""The native probe workspace's generated files and its tree digest (W04-4a, CONF-ENF-004).

The probes under probes/enforcement/ are Rust, standard library only, built as static musl binaries for x86_64 and
aarch64. Until the R12 Rust profile exists they compile only on the author's machine (owner decision Q-T2 (b),
2026-10-13), so CI checks them here, with the standard library only. This module writes the three generated Rust files:
- common/src/nr.rs: the syscall numbers the probes call through musl's syscall(), from seccomp v2's Linux v6.12 table;
- tg05_clocks/src/expected.rs: the role cgroup paths and interpreters, native qualification v3 schema constants;
- common/src/tree.rs: the probe tree's digest, so every timeline names the source it was built from.
test_probes.py regenerates each and compares bytes, so none can drift from the contracts or the tree unseen.
"""
from __future__ import annotations

import hashlib
from pathlib import Path

import _models

ROOT = Path(__file__).resolve().parents[2]
PROBES = ROOT / "probes/enforcement"
SECCOMP_TABLE = "architecture/seccomp-allowlists-v2/syscalls.json"
NATIVE_SCHEMA = "architecture/native-profile-v3/qualification.schema.json"
# The Linux-specific calls the probes make through musl's syscall(); POSIX calls use musl's own functions.
SYSCALLS = ("pidfd_open", "pidfd_send_signal")
ARCHES = ("x86_64", "aarch64")
ROLES = ("SERVER", "OBSERVER", "BROKER", "WORKER", "EFFECT_GATE")
TREE_FILE = "common/src/tree.rs"
EVIDENCE_FILE = "BUILD_EVIDENCE.json"
# Files outside the digest: the digest's own file, and the author's build evidence that names the digest.
UNDIGESTED = {TREE_FILE, EVIDENCE_FILE}


def nr_rs() -> str:
    table = _models.data(SECCOMP_TABLE)
    lines = ["//! Generated by tests/enforcement/_probes.py from the pinned seccomp v2 syscall table",
             "//! (" + SECCOMP_TABLE + ", Linux " + table["kernel"]["tag"] + " commit " + table["kernel"]["commit"] + ").",
             "//! Do not edit: tests/enforcement/test_probes.py regenerates this file and compares bytes.", ""]
    for arch in ARCHES:
        lines.append('#[cfg(target_arch = "%s")]' % arch)
        lines.append("mod numbers {")
        for name in SYSCALLS:
            row = table["syscalls"][name][arch]
            lines.append("    /// %s" % row["cite"])
            lines.append("    pub const %s: i64 = %d;" % (name.upper(), row["nr"]))
        lines.append("}")
        lines.append("")
    lines.append("pub use numbers::*;")
    return "\n".join(lines) + "\n"


def expected_rs() -> str:
    """tg05_clocks/src/expected.rs: each resident role's cgroup path and interpreter, the schema constants of native
    qualification v3 (a role with an interpreter is a CPython role)."""
    roles = _models.data(NATIVE_SCHEMA)["$defs"]["roles"]["properties"]
    lines = ["//! Generated by tests/enforcement/_probes.py from the pinned contract snapshots. Do not edit:",
             "//! tests/enforcement/test_probes.py regenerates this file and compares bytes.", "",
             "/// Each role's cgroup path and interpreter (None: a native static role), from",
             "/// %s $defs.roles.<role>.cgroup.path and .interpreterPath (const)." % NATIVE_SCHEMA,
             "pub const ROLES: [(&str, &str, Option<&str>); %d] = [" % len(ROLES)]
    for role in ROLES:
        row = roles[role]["properties"]
        interpreter = row["interpreterPath"]["const"]
        lines.append('    ("%s", "%s", %s),' % (role, row["cgroup"]["properties"]["path"]["const"],
                                               "None" if interpreter is None else 'Some("%s")' % interpreter))
    lines.append("];")
    return "\n".join(lines) + "\n"


def tree_files() -> list[str]:
    """Every regular file under probes/enforcement, relative and sorted (directories are walked, links refused)."""
    found = []
    for path in sorted(PROBES.rglob("*")):
        if path.is_symlink():
            raise ValueError("link in the probe tree: %s" % path)
        if path.is_file():
            found.append(path.relative_to(PROBES).as_posix())
    return found


def tree_digest() -> str:
    """sha256 over one line per digested file, '<path> <sha256 of its bytes>', in path order."""
    lines = []
    for relative in tree_files():
        if relative not in UNDIGESTED:
            lines.append("%s %s\n" % (relative, hashlib.sha256(_models._regular(PROBES / relative)).hexdigest()))
    return hashlib.sha256("".join(lines).encode()).hexdigest()


def tree_rs() -> str:
    return ("//! Generated by tests/enforcement/_probes.py: the sha256 of the probe tree (every file under probes/enforcement\n"
            "//! except this one and BUILD_EVIDENCE.json), so each timeline names the reviewed source it was built from.\n"
            'pub const PROBE_TREE: &str = "%s";\n' % tree_digest())


GENERATED = {"common/src/nr.rs": nr_rs, "tg05_clocks/src/expected.rs": expected_rs, TREE_FILE: tree_rs}


def write_generated() -> None:
    """Author tool: rewrite the generated files (the tree digest last, since it covers the other two)."""
    for relative, make in GENERATED.items():
        (PROBES / relative).write_text(make())
